 1→import { spawn } from "node:child_process";
 2→import { logger } from "../utils/logger.js";
 3→
 4→export interface SpawnOptions {
 5→	command: string;
 6→	args: string[];
 7→	timeout?: number;
 8→	cwd?: string;
 9→	env?: Record<string, string | undefined>;
10→	stdin?: string;
11→}
12→
13→export interface SpawnResult {
14→	stdout: string;
15→	stderr: string;
16→	exitCode: number;
17→	durationMs: number;
18→	timedOut: boolean;
19→}
20→
21→const DEFAULT_TIMEOUT = 120_000; // 2 minutes
22→
23→export async function spawnAgent(options: SpawnOptions): Promise<SpawnResult> {
24→	const { command, args, timeout = DEFAULT_TIMEOUT, cwd, env, stdin } = options;
25→
26→	const controller = new AbortController();
27→	const startTime = Date.now();
28→
29→	logger.debug(`Spawning: ${command} ${args.join(" ")}`);
30→
31→	return new Promise<SpawnResult>((resolve) => {
32→		const stdio: ["ignore" | "pipe", "pipe", "pipe"] = [
33→			stdin === undefined ? "ignore" : "pipe",
34→			"pipe",
35→			"pipe",
36→		];
37→
38→		const child = spawn(command, args, {
39→			cwd,
40→			env: env ? { ...process.env, ...env } : process.env,
41→			signal: controller.signal,
42→			stdio,
43→		});
44→
45→		const stdoutChunks: Buffer[] = [];
46→		const stderrChunks: Buffer[] = [];
47→		let timedOut = false;
48→
49→		const timer = setTimeout(() => {
50→			timedOut = true;
51→			controller.abort();
52→		}, timeout);
53→
54→		child.stdout?.on("data", (chunk: Buffer) => stdoutChunks.push(chunk));
55→		child.stderr?.on("data", (chunk: Buffer) => stderrChunks.push(chunk));
56→
57→		if (stdin !== undefined && child.stdin) {
58→			child.stdin.end(stdin);
59→		} else {
60→			child.stdin?.end();
61→		}
62→
63→		child.on("close", (code) => {
64→			clearTimeout(timer);
65→			const durationMs = Date.now() - startTime;
66→			const stdout = Buffer.concat(stdoutChunks).toString("utf-8");
67→			const stderr = Buffer.concat(stderrChunks).toString("utf-8");
68→
69→			logger.debug(`Process exited: code=${code}, duration=${durationMs}ms`);
70→
71→			resolve({
72→				stdout,
73→				stderr,
74→				exitCode: code ?? 1,
75→				durationMs,
76→				timedOut,
77→			});
78→		});
79→
80→		child.on("error", (err) => {
81→			clearTimeout(timer);
82→			const durationMs = Date.now() - startTime;
83→
84→			logger.error(`Process error: ${err.message}`);
85→
86→			resolve({
87→				stdout: Buffer.concat(stdoutChunks).toString("utf-8"),
88→				stderr: err.message,
89→				exitCode: 1,
90→				durationMs,
91→				timedOut,
92→			});
93→		});
94→	});
95→}
