 1→import type { AgentConfig, AgentId, ExecutionOptions } from "./types.js";
 2→import { BaseAgent } from "./base-agent.js";
 3→import type { SpawnOptions } from "../orchestrator/executor.js";
 4→
 5→export class GeminiAgent extends BaseAgent {
 6→	readonly id: AgentId = "gemini";
 7→	readonly displayName = "Gemini CLI";
 8→	readonly cliCommand = "gemini";
 9→
10→	constructor(config: AgentConfig) {
11→		super(config);
12→	}
13→
14→	protected buildSpawnOptions(options: ExecutionOptions, model: string): SpawnOptions {
15→		const args = [
16→			"-m",
17→			model,
18→			"-p",
19→			options.prompt,
20→			"--output-format",
21→			"stream-json",
22→			"--sandbox",
23→		];
24→
25→		return {
26→			command: this.cliCommand,
27→			args,
28→			timeout: options.timeout,
29→			cwd: options.cwd,
30→			stdin: options.context,
31→		};
32→	}
33→
34→	protected override parseOutput(stdout: string, _stderr: string): string {
35→		// stream-json outputs newline-delimited JSON objects
36→		// Extract text content from the stream
37→		const lines = stdout.trim().split("\n");
38→		const textParts: string[] = [];
39→
40→		for (const line of lines) {
41→			try {
42→				const obj = JSON.parse(line);
43→				if (obj.text) textParts.push(obj.text);
44→				else if (obj.response) textParts.push(obj.response);
45→				else if (obj.content) textParts.push(obj.content);
46→			} catch {
47→				// Not JSON, collect as raw text
48→				if (line.trim()) textParts.push(line);
49→			}
50→		}
51→
52→		return textParts.join("") || stdout.trim();
53→	}
54→}
