 50→			return {
 51→				agent: this.id,
 52→				model,
 53→				content: "",
 54→				durationMs: result.durationMs,
 55→				exitCode: 124,
 56→				error: `Timed out after ${options.timeout ?? 120000}ms`,
 57→			};
 58→		}
 59→
 60→		// Try to read from output file first, fallback to stdout
 61→		let content = "";
